import React from "react";
import { Text, View } from "react-native";
import { ICON_GLYPHS } from "./iconGlyphs";

/**
 * Thin-stroke icons (lucide-style, ISC licence) rendered from the bundled icon font
 * assets/fonts/KartenIcons.ttf (generated by scripts/make_icon_font.py) — no native SVG dependency.
 */
export type IconName = keyof typeof ICON_GLYPHS;
export const ICON_FONT = "KartenIcons";

export function Icon({ name, size = 22, color = "#111", stroke = 1.6 }: { name: IconName; size?: number; color?: string; stroke?: number }) {
  const glyph = ICON_GLYPHS[name][stroke >= 1.9 ? 1 : 0];
  return (
    <Text
      accessible={false}
      importantForAccessibility="no"
      allowFontScaling={false}
      style={{
        fontFamily: ICON_FONT,
        fontWeight: "400",
        fontSize: size,
        lineHeight: size,
        width: size,
        height: size,
        color,
        textAlign: "center",
        includeFontPadding: false,
        textAlignVertical: "center",
      }}
    >
      {glyph}
    </Text>
  );
}

/** Small Austrian flag (red-white-red). */
export function AtFlag({ width = 20 }: { width?: number }) {
  const h = Math.round((width * 2) / 3);
  return (
    <View style={{ width, height: h, borderRadius: Math.max(2, width / 10), overflow: "hidden", backgroundColor: "#C8102E", justifyContent: "center" }}>
      <View style={{ height: h / 3, backgroundColor: "#FFFFFF" }} />
    </View>
  );
}

/** Half of a ring, clipped to one side; rotated to reveal `deg` degrees of arc (0–180). */
function HalfArc({ size, stroke, color, side, deg }: { size: number; stroke: number; color: string; side: "right" | "left"; deg: number }) {
  const half = size / 2;
  return (
    <View style={{ position: "absolute", top: 0, left: side === "right" ? half : 0, width: half, height: size, overflow: "hidden" }}>
      <View
        style={{
          position: "absolute",
          top: 0,
          left: side === "right" ? -half : 0,
          width: size,
          height: size,
          transform: [{ rotate: `${deg}deg` }],
        }}
      >
        {/* ring half that starts on the opposite side, so rotation sweeps it in clockwise */}
        <View style={{ position: "absolute", top: 0, left: side === "right" ? 0 : half, width: half, height: size, overflow: "hidden" }}>
          <View
            style={{
              position: "absolute",
              top: 0,
              left: side === "right" ? 0 : -half,
              width: size,
              height: size,
              borderRadius: half,
              borderWidth: stroke,
              borderColor: color,
            }}
          />
        </View>
      </View>
    </View>
  );
}

/** Progress ring for achievements (pure Views: two clipped, rotated half-rings). */
export function Ring({ size = 44, progress, color, track, stroke = 2 }: { size?: number; progress: number; color: string; track: string; stroke?: number }) {
  const p = Math.max(0, Math.min(1, progress));
  return (
    <View style={{ width: size, height: size }}>
      <View style={{ position: "absolute", width: size, height: size, borderRadius: size / 2, borderWidth: stroke, borderColor: track }} />
      {p > 0 ? <HalfArc size={size} stroke={stroke} color={color} side="right" deg={Math.min(p, 0.5) * 360} /> : null}
      {p > 0.5 ? <HalfArc size={size} stroke={stroke} color={color} side="left" deg={(p - 0.5) * 360} /> : null}
    </View>
  );
}
